import { useSec, useIn, useFade, useProgress } from "@/jbm/motion/hooks"

// Render inside a Remotion <Composition> or <Player>: hooks run in the component body.
export function TimelineReadout() {
  const seconds = useSec()
  const entrance = useIn(0.2)
  const opacity = useFade(0.2)
  const progress = useProgress(0.2, 100, 1.5)
  return (
    <div style={{ opacity, transform: `translateY(${(1 - entrance) * 30}px)` }}>
      {progress.toFixed(0)}% at {seconds.toFixed(2)}s
    </div>
  )
}

