import schema from "./scene-spec.schema.json" // curl -o scene-spec.schema.json https://jbm-ui.bns.studio/schemas/scene-spec.json

// Placeholders: the YAML source, seconds from scene start per phrase, and a translator.
declare const yamlText: string
declare const timings: Record<string, number>
declare const translate: (text: string) => string

const validate = new Ajv2020({ allErrors: true }).compile(schema)
