import { useCurrentFrame, interpolate } from "remotion"
import { Ejes } from "@/jbm/ui/ejes"

function Brujula() {
  const frame = useCurrentFrame()
  const h = interpolate(frame, [120, 168], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
  const v = interpolate(frame, [204, 240], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
  return (
    <svg viewBox="0 0 1920 1080">
      <Ejes box={{ x: 120, y: 90, w: 1680, h: 830 }} h={h} v={v}
        labels={{ top: "hacer", bottom: "entender", left: "aprender", right: "trabajar" }} />
    </svg>
  )
}

